// Uma consulta por objeto, na ordem em que fn_run_ingest_batch resolve as FKs.
// O piso de 12 meses e a decisao de janela registrada no validation-log: 6 meses
// custavam quase o mesmo que 12, e 12 compra comparacao ano contra ano.
const PISO = '2025-09-14T00:00:00Z';
const INST = 'https://loupen.my.salesforce.com';
const V = 'v67.0';

// Watermark por objeto, vinda de sync_state. Ausente = primeira carga daquele objeto.
const wm = {};
for (const it of $input.all()) {
  if (it.json && it.json.object && it.json.wm) wm[it.json.object] = it.json.wm;
}

const desde = (obj) => wm[obj] || PISO;

const OBJETOS = [
  { tipo: 'Owner', soql: `SELECT Id, Name, Email FROM User WHERE IsActive = true` },
  // A taxa de cambio e DADO DE ORIGEM, nao constante de codigo. Sem ela o
  // banco soma dolar com real: das 8.073 oportunidades, 1.344 estao em USD e
  // 859 em MXN -- e o erro nao tem sinal fixo, porque peso e dolar puxam para
  // lados opostos. Lido inteiro a cada execucao, de proposito — sao 3
  // linhas e a taxa muda sozinha; filtrar por watermark congelaria um cambio
  // antigo e a receita pararia de bater com o Salesforce.
  { tipo: 'CurrencyType', soql: `SELECT Id, IsoCode, ConversionRate, IsCorporate, IsActive, DecimalPlaces FROM CurrencyType` },
  // O Salesforce ja declara, por estagio, o que nos escrevemos a mao em
  // opportunity_stage_fase: IsWon, IsClosed, DefaultProbability e
  // ForecastCategoryName. Sao 114 estagios na org contra 29 mapeados por
  // julgamento. Ingerir a declaracao da origem nao substitui o nosso
  // agrupamento em 6 fases — torna ele auditavel contra o que o CRM diz.
  //
  // Foi essa leitura que derrubou um palpite: 'Pending Sale' parece venda
  // fechada e o Salesforce diz IsWon=false, IsClosed=false, prob 95%.
  // Mapear por intuicao teria inventado 14 vendas.
  //
  // Sem watermark, como CurrencyType: a tabela e pequena e a classificacao
  // de um estagio pode ser reconfigurada no Setup sem tocar em registro
  // nenhum — ler incremental congelaria a regra antiga.
  { tipo: 'OpportunityStage', soql: `SELECT Id, MasterLabel, ApiName, IsActive, IsWon, IsClosed, DefaultProbability, ForecastCategoryName, SortOrder FROM OpportunityStage` },
  { tipo: 'Account', soql: `SELECT Id, Name FROM Account WHERE SystemModstamp >= ${desde('Account')}` },
  { tipo: 'Lead', soql: `SELECT Id, Name, Company, Email, Phone, Status, LeadSource, Identificador_RD__c, UTM_Source__c, UTM_Campaign__c, Campanha_LinkedIn__c, ConvertedAccountId, ConvertedOpportunityId, OwnerId, CreatedDate FROM Lead WHERE SystemModstamp >= ${desde('Lead')}` },
  { tipo: 'Opportunity', soql: `SELECT Id, RecordType.Name, StageName, LeadSource, Amount, CurrencyIsoCode, MRR__c, Termo_do_Contrato__c, AccountId, OwnerId, CreatedDate, CloseDate FROM Opportunity WHERE SystemModstamp >= ${desde('Opportunity')}` }
];

// Um batch_id para a execucao inteira: fn_run_ingest_batch e chamada UMA vez no fim,
// e resolve Owner -> Account -> Lead -> Opportunity na ordem interna dela.
const batchId = 'sf-' + new Date().toISOString().replace(/[-:.]/g,'').slice(0,15) + 'Z';
const coletadoEm = new Date().toISOString();

return OBJETOS.map(o => ({ json: {
  batch_id: batchId,
  object_type: o.tipo,
  collected_at: coletadoEm,
  url: `${INST}/services/data/${V}/query?q=${encodeURIComponent(o.soql)}`
}}));

// Achata as paginas em linhas de staging. Cada item de entrada e UMA pagina da
// resposta do Salesforce.
const meta = $('Montar consultas').all().map(i => i.json);
const saida = [];
const entrada = $input.all();

for (let i = 0; i < entrada.length; i++) {
  const pagina = entrada[i].json;
  const m = meta[entrada[i].pairedItem?.item ?? 0] || meta[0];
  for (const r of (pagina.records || [])) {
    delete r.attributes;
    if (r.RecordType && typeof r.RecordType === 'object') delete r.RecordType.attributes;
    saida.push({ json: { batch_id: m.batch_id, object_type: m.object_type, collected_at: m.collected_at, payload: r } });
  }
  // Guarda de truncamento: se a paginacao nao completou, a execucao FALHA em voz
  // alta em vez de gravar um lote parcial que a reconciliacao chamaria de 'ok'.
  if (pagina.done === false) {
    throw new Error(`Paginacao incompleta em ${m.object_type}: done=false na ultima pagina recebida. Lote abortado de proposito -- carga parcial silenciosa e o defeito que esta ingestao existe para nao ter.`);
  }
}

if (saida.length === 0) throw new Error('Nenhum registro retornado pelo Salesforce. Verifique a watermark em sync_state.');
return saida;
